	s.mux.HandleFunc("GET /api/v1/frontend/revision", s.handleFrontendRevision)
	s.mux.HandleFunc("GET /api/v1/mcp-catalog", s.handleMCPCatalog)
	s.mux.HandleFunc("GET /api/v1/public/demo", s.handlePublicDemo)
	s.mux.HandleFunc("GET /api/v1/public/site", s.handlePublicSite)
	s.mux.HandleFunc("GET /api/v1/public/hosting", s.requireLanding(s.handlePublicHosting))
	s.mux.HandleFunc("GET /api/v1/public/hosting/subdomain-check", s.requireLanding(s.handlePublicCheckSubdomain))
	s.mux.HandleFunc("POST /api/v1/public/hosting/orders", s.requireLanding(s.handlePublicCreateOrder))
