	s.mux.Handle("GET /api/v1/me/hosting/plan", s.requireAuthV2(http.HandlerFunc(s.handleMyPlan)))
	s.mux.Handle("GET /api/v1/me/hosting/orders",s.requireAuthV2(http.HandlerFunc(s.handleListMyOrders)))
	s.mux.Handle("GET /api/v1/hosting/orders", s.requireRole(auth.SuperadminRole, http.HandlerFunc(s.handleListOrders)))
